// Parse Evolution API message
const body = $input.first().json.body || $input.first().json;

// Extract message data
const data = body.data || body;
const key = data.key || {};
const remoteJid = key.remoteJid || '';
const phone = remoteJid.replace('@s.whatsapp.net', '').replace('@g.us', '');
const fromMe = key.fromMe || false;

// Skip our own messages
if (fromMe) {
  return [];
}

// Determine message type and content
const message = data.message || {};
const messageType = data.messageType || 'unknown';

let textContent = '';
let msgType = 'text';

if (messageType === 'conversation') {
  textContent = message.conversation || '';
  msgType = 'text';
} else if (messageType === 'extendedTextMessage') {
  textContent = (message.extendedTextMessage || {}).text || '';
  msgType = 'text';
} else if (messageType === 'audioMessage') {
  msgType = 'audio';
  textContent = '';
} else if (messageType === 'imageMessage') {
  msgType = 'image';
  textContent = (message.imageMessage || {}).caption || '[صورة]';
} else if (messageType === 'documentMessage') {
  msgType = 'document';
  textContent = '[مستند: ' + ((message.documentMessage || {}).fileName || 'unknown') + ']';
} else {
  msgType = 'text';
  textContent = JSON.stringify(message).substring(0, 200);
}

return [{
  json: {
    phone: phone,
    remoteJid: remoteJid,
    messageType: msgType,
    textContent: textContent,
    rawMessage: message,
    timestamp: new Date().toISOString()
  }
}];

// Check Lead Exists returns HTTP response: items[0].json is the array of leads
const phone = $('Parse Message').first().json.phone;
const rawResult = $input.first().json;

// n8n HTTP Request يرجع كل عنصر في الـ array كـ item منفصل
// لذلك نستخدم $input.all() ونبحث عن أي item فيه lead_id
const allItems = $input.all().map(i => i.json);
const existingLead = allItems.find(r => r && r.lead_id) || null;

if (existingLead && existingLead.lead_id) {
  // Existing lead
  return [{
    json: {
      isNew: false,
      lead: existingLead,
      phone: phone
    }
  }];
} else {
  // New lead
  return [{
    json: {
      isNew: true,
      lead: null,
      phone: phone
    }
  }];
}

// Build context for AI Agent
// Get Chat History is HTTP Request - returns array in items[0].json
// n8n يرجع كل رسالة كـ item منفصل — نستخدم .all()
const history = $('Get Chat History').all().map(i => i.json).filter(m => m && m.message);
const leadData = $('New or Existing?').first().json;
const userMessage = $('Parse Message').first().json.textContent;
const phone = $('Parse Message').first().json.phone;

// Format conversation history (reverse to chronological order)
const chatHistory = history.reverse().map(msg => {
  const role = msg.role === 'user' ? 'العميل' : 'ليلى';
  return `${role}: ${msg.message}`;
}).join('\n');

// Lead context
let leadContext = '';
if (leadData.lead) {
  const l = leadData.lead;
  leadContext = `\n--- بيانات العميل ---\n`;
  leadContext += `الرقم: ${phone}\n`;
  if (l.name) leadContext += `الاسم: ${l.name}\n`;
  if (l.stage) leadContext += `المرحلة: ${l.stage}\n`;
  if (l.destination) leadContext += `الوجهة: ${l.destination}\n`;
  if (l.pax_adults) leadContext += `كبار: ${l.pax_adults}\n`;
  if (l.pax_children) leadContext += `أطفال: ${l.pax_children} (أعمار: ${JSON.stringify(l.children_ages || [])})\n`;
  if (l.travel_dates) leadContext += `التواريخ: ${l.travel_dates}\n`;
  if (l.offer_amount_usd) leadContext += `آخر عرض: $${l.offer_amount_usd}\n`;
  if (l.objection_type) leadContext += `اعتراض سابق: ${l.objection_type}\n`;
  if (l.assigned_to) leadContext += `مسؤول: ${l.assigned_to}\n`;
} else {
  leadContext = `\n--- عميل جديد ---\nالرقم: ${phone}\nلا توجد بيانات سابقة\n`;
}

// تعليمة التعريف بالنفس بناء على isNew
const introInstruction = leadData.isNew
  ? '\n⚠️ هذا عميل جديد — عرّفي نفسك في بداية ردك: "أنا ليلى من أركاديا للسياحة".'
  : '\n⚠️ هذا عميل سابق — لا تعرّفي نفسك أبداً. ردّي مباشرة بدون مقدمة.';

return [{
  json: {
    userMessage: userMessage,
    chatHistory: chatHistory,
    chatHistoryRaw: history,   // مصفوفة الرسائل الكاملة لـ Fetch Pricing
    leadContext: leadContext + introInstruction,
    phone: phone,
    isNew: leadData.isNew
  }
}];

const aiResponse = $input.first().json.output || '';
const phone = $('Parse Message').first().json.phone;
const remoteJid = $('Parse Message').first().json.remoteJid;
return [{ json: { phone, remoteJid, response: aiResponse } }];

const result = $input.first().json;
const output = result?.choices?.[0]?.message?.content || 'عذراً، حدث خطأ. جرّب مرة ثانية.';
const phone = $('Parse Message').first().json.phone;
const remoteJid = $('Parse Message').first().json.remoteJid;
return [{ json: { output, phone, remoteJid } }];

const context = $('Build AI Context').first().json;
const userMessage = context.userMessage || '';
const leadContext = context.leadContext || '';
const chatHistory = context.chatHistory || '';
const chatHistoryRaw = context.chatHistoryRaw || [];
const phone = context.phone || '';

// ── قراءة نتيجة Extract Intent (AI) ────────────────────────────────────────
let destination = '', city = '', city2 = '', nights = 0, adults = 0, childrenAges = [];

try {
  const aiRaw = $('Extract Intent').first().json;
  const aiContent = aiRaw?.choices?.[0]?.message?.content || '{}';
  // نظّف الرد من أي نص خارج الـ JSON
  const jsonMatch = aiContent.match(/\{[\s\S]*\}/);
  const extracted = jsonMatch ? JSON.parse(jsonMatch[0]) : {};

  destination    = extracted.destination    || '';
  city           = extracted.city           || '';
  city2          = extracted.city2          || '';
  nights         = parseInt(extracted.nights)   || 0;
  adults         = parseInt(extracted.adults || extracted.adult) || 0;
  childrenAges   = Array.isArray(extracted.children_ages) ? extracted.children_ages : [];
} catch(e) {
  // fallback: leave zeros
}

// Map destination to country code
let destCode = '';
if (destination === 'Kazakhstan') destCode = 'KZ';
if (destination === 'Russia')     destCode = 'RU';
if (destination === 'Poland')     destCode = 'PL';
if (destination === 'Uzbekistan') destCode = 'UZ';
if (destination === 'Ukraine')    destCode = 'UA';

// Default city if not extracted
  if (destination === 'Kazakhstan' && !city) city = 'Almaty';
  if (destination === 'Russia'     && !city) city = 'Moscow';

// Determine action
let pricingData = '';
const hasPricingIntent = true;  // AI already extracted — trust it

if (destination && nights > 0 && adults > 0) {
  if (city2 && destination === 'Russia') {
    // Multi-city: calculate both cities
    pricingData = `FETCH_PRICING:${destination}|${city}+${city2}|${nights}|${adults}`;
  } else {
    pricingData = `FETCH_PRICING:${destination}|${city}|${nights}|${adults}`;
  }
} else if (destination) {
  pricingData = 'NEED_MORE_INFO';
}

return [{ json: {
  ...context,
  pricingIntent : !!destination,
  destination,
  destCode,
  city,
  city2,
  nights,
  adults,
  childrenAges,
  pricingData
}}];

const prev        = $('Fetch Pricing').first().json;
const city2Raw    = prev.city2 || '';
const isMultiCity = !!(city2Raw && prev.destination === 'Russia');
// للمدينتين: قسّم الليالي — الثلثان للأولى والثلث للثانية (أو 50/50)
const nightsCity1 = isMultiCity ? Math.ceil(prev.nights / 2) : prev.nights;
const nightsCity2 = isMultiCity ? Math.floor(prev.nights / 2) : 0;
const nights      = isMultiCity ? nightsCity1 : (prev.nights || 0);
const adults      = prev.adults  || 1;
const destination = prev.destination || '';
const today       = new Date().toISOString().split('T')[0];
const clientType  = prev.clientType || 'B2C';   // B2C=20% / B2B=15%
const markup      = clientType === 'B2B' ? 1.15 : 1.20;

// ── FX Rates (مؤقت — لاحقاً يُربط بـ API) ──────────────────────────────────
const fxRateMap = { Kazakhstan: 1/498, Russia: 1/90, Poland: 1/4, Uzbekistan: 1/12700 };
const fxRate    = fxRateMap[destination] || 0.002;

// ── Services (hardcoded من Supabase — يُحدَّث عند التغيير) ──────────────────
const SERVICES = {
  Kazakhstan: {
    transfer : { Sedan:{max:3,price:10000}, Minivan:{max:5,price:15000}, Sprinter:{max:18,price:25000} },
    dailyRent: { Sedan:{max:3,price:35000}, Minivan:{max:5,price:42500}, Sprinter:{max:18,price:80000} },
    sim      : 6000
  },
  Russia: {
    transfer : { Sedan:{max:3,price:6240},  Minivan:{max:6,price:7800},  Sprinter:{max:18,price:20000} },
    dailyRent: { Sedan:{max:3,price:8000},  Minivan:{max:6,price:12000}, Sprinter:{max:18,price:25000} },
    sim      : 0      // SIM اختياري في روسيا
  },
  Poland: {
    transfer : { Sedan:{max:3,price:50},    Minivan:{max:6,price:70},    Sprinter:{max:18,price:120}  },
    dailyRent: { Sedan:{max:3,price:80},    Minivan:{max:6,price:120},   Sprinter:{max:18,price:200}  },
    sim      : 30
  }
};

function pickCar(svcGroup, pax) {
  if (!svcGroup) return null;
  if (pax <= 3) return { type: 'Sedan',   ...svcGroup.Sedan   };
  if (pax <= 6) return { type: 'Minivan', ...svcGroup.Minivan };
  return              { type: 'Sprinter',...svcGroup.Sprinter };
}

// حساب خدمات بالعملة المحلية (بدون markup)
function servicesRaw(dest, pax, nts) {
  const svc     = SERVICES[dest];
  if (!svc || nts <= 0) return { raw: 0, lines: [] };
  const tourDays   = Math.max(nts - 1, 0);
  const car        = pickCar(svc.transfer, pax);
  const rentCar    = pickCar(svc.dailyRent, pax);
  const transferKZT   = car     ? car.price     * 2        : 0;
  const dailyRentKZT  = rentCar ? rentCar.price * tourDays : 0;
  const simKZT        = svc.sim * pax;
  const raw = transferKZT + dailyRentKZT + simKZT;
  const cur = dest === 'Russia' ? 'RUB' : dest === 'Poland' ? 'PLN' : 'KZT';
  return {
    raw,
    lines: [
      transferKZT > 0 ? `نقل مطار (${car ? car.type : '?'}) ذهاب+إياب: ${transferKZT.toLocaleString()} ${cur}` : null,
      dailyRentKZT > 0 ? `سيارة يومية × ${tourDays} أيام: ${dailyRentKZT.toLocaleString()} ${cur}` : null,
      simKZT > 0 ? `SIM × ${pax} أشخاص: ${simKZT.toLocaleString()} ${cur}` : null
    ].filter(Boolean)
  };
}

// ── Data from nodes ─────────────────────────────────────────────────────────
const hotelList    = ($('Get Hotels').all()    || []).map(i => i.json).filter(h => h?.Hotel_ID);
const ratePlanList = ($('Get Rate Plans').all() || []).map(i => i.json).filter(r => r?.Hotel_ID);
const seasonList   = ($('Get Seasons').all()   || []).map(i => i.json).filter(s => s?.Season_ID);
const roomList     = ($('Get Room Types').all() || []).map(i => i.json).filter(r => r?.Room_ID);

const hotels  = {}; hotelList.forEach(h  => hotels[h.Hotel_ID]   = h);
const rooms   = {}; roomList.forEach(r   => rooms[r.Room_ID]     = r);
const seasons = {}; seasonList.forEach(s => seasons[s.Season_ID] = s);

// ── خدمات مشتركة (نفس المبلغ لكل الفنادق) ──────────────────────────────────
const { raw: svcRaw, lines: svcLines } = servicesRaw(destination, adults, nights);

// ── Group rate plans by hotel — seasons نشطة فقط ────────────────────────────
const hotelRooms = {};   // hotelId → [{ roomRate (DBL), roomType }]

ratePlanList.forEach(rp => {
  const hotel  = hotels[rp.Hotel_ID];
  const room   = rooms[rp.Room_ID];
  const season = seasons[rp.Season_ID];
  if (!hotel || !room || !season) return;

  // ✅ تحقق صريح: today بين Start_Date و End_Date
  const sStart = season.Start_Date || '';
  const sEnd   = season.End_Date   || '';
  if (!sStart || !sEnd || !(sStart <= today && today <= sEnd)) return;

  // دائماً نستخدم DBL للزوجين، SGL للفرد
  let roomRate = 0, numRooms = 1;
  if      (adults <= 1) roomRate = parseFloat(rp.SGL_Rate) || 0;
  else if (adults <= 2) roomRate = parseFloat(rp.DBL_Rate) || 0;
  else if (adults <= 3) roomRate = parseFloat(rp.TRP_Rate) || parseFloat(rp.DBL_Rate) || 0;
  else { roomRate = parseFloat(rp.DBL_Rate) || 0; numRooms = Math.ceil(adults / 2); }
  if (!roomRate) return;

  if (!hotelRooms[rp.Hotel_ID]) hotelRooms[rp.Hotel_ID] = { hotel, rooms: [] };
  hotelRooms[rp.Hotel_ID].rooms.push({ roomType: room.Room_Type_Name, roomRate, numRooms });
});

// لكل فندق: رتّب من الأرخص (DBL) واختر أرخص غرفة
const results = [];
Object.entries(hotelRooms).forEach(([hotelId, { hotel, rooms: hotelRoomsArr }]) => {
  hotelRoomsArr.sort((a, b) => a.roomRate - b.roomRate);
  const best = hotelRoomsArr[0];

  // حساب كلفة الإقامة الصافية (بدون markup)
  const hotelRaw = best.roomRate * nights * best.numRooms;

  // الإجمالي الصافي → ثم markup واحدة على الكل
  const totalRaw = hotelRaw + svcRaw;
  const totalUSD = Math.round(totalRaw * fxRate * markup);

  // تفصيل (للعرض فقط — بدون markup)
  const hotelUSD = Math.round(hotelRaw * fxRate);
  const svcUSD   = Math.round(svcRaw   * fxRate);

  if (totalUSD > 0) {
    results.push({
      hotelName : hotel.Hotel_Name_AR || hotel.Hotel_Name,
      stars     : parseInt(hotel.Star_Rating) || 4,
      roomType  : best.roomType,
      numRooms  : best.numRooms,
      hotelUSD, svcUSD, totalUSD
    });
  }
});

// ترتيب: نجوم تصاعدي ثم سعر إجمالي تصاعدي
results.sort((a, b) => a.stars - b.stars || a.totalUSD - b.totalUSD);

const fourStar = results.filter(r => r.stars === 4);
const fiveStar = results.filter(r => r.stars === 5);

const options = [];
if (fourStar.length > 0) options.push({ tier: 'اقتصادية', ...fourStar[0] });
if (fourStar.length > 1) options.push({ tier: 'فضية',     ...fourStar[Math.floor(fourStar.length / 2)] });
if (fiveStar.length > 0) options.push({ tier: 'ذهبية',    ...fiveStar[0] });

let pricingText = '\n--- أسعار متاحة ---\n';
if (!options.length) {
  pricingText = `\n--- لا توجد أسعار للتواريخ الحالية (${Object.keys(hotelRooms).length} فنادق, ${ratePlanList.length} خطط). اقترحي للعميل تواريخ مستقبلية أو حوّليه للمدير. ---\n`;
} else {
  // قائمة المشمولات الاحترافية حسب الوجهة
  const tourDays = Math.max(nights - 1, 1);
  const cities = { Kazakhstan:'ألماتي', Russia:'موسكو', Poland:'وارسو', Uzbekistan:'طشقند', Ukraine:'كييف' };
  const repCity = cities[destination] || destination;

  function buildInclusions(dest, nts) {
    const td = Math.max(nts - 1, 1);
    const base = [
      `🏨 الإقامة في الفندق مع الإفطار اليومي`,
      `🚗 الاستقبال والتوصيل من وإلى المطار`,
      `🗺️ ${td} جولة${td > 1 ? ' سياحية' : ' سياحية'} بسيارة خاصة مع سائق`,
      `🎧 خدمة عملاء أركاديا على مدار الساعة`,
    ];
    if (dest !== 'Russia') base.push(`📱 شريحة اتصال وإنترنت محلية`);
    base.push(`👨‍💼 مندوب أركاديا في ${repCity} لمتابعتكم`);
    return base.join('\n');
  }

  options.forEach(opt => {
    pricingText += `\nباقة ${opt.tier}: ${opt.hotelName} ${'⭐'.repeat(opt.stars)}\n`;
    pricingText += `${nights} ليالي | ${opt.numRooms > 1 ? opt.numRooms+' غرف' : 'غرفة'} ${opt.roomType} | إفطار يومي\n`;
    pricingText += `السعر الإجمالي: $${opt.totalUSD} USD\n`;
    pricingText += `يشمل:\n${buildInclusions(destination, nights)}\n`;
  });


}

// ── Multi-city: حساب المدينة الثانية ────────────────────────────────────────
if (isMultiCity && nightsCity2 > 0) {
  const nights2 = nightsCity2;
  const city2Hotels = hotelList.filter(h => h.City === city2Raw);
  const opts2 = [];
  const { raw: svcRaw2, lines: svcLines2 } = servicesRaw(destination, adults, nights2);

  city2Hotels.forEach(hotel => {
    const hotelRooms2 = {};
    ratePlanList.forEach(rp => {
      const room   = rooms[rp.Room_ID];
      const season = seasons[rp.Season_ID];
      if (!room || !season) return;
      if (rp.Hotel_ID !== hotel.Hotel_ID) return;
      const sStart = season.Start_Date || '';
      const sEnd   = season.End_Date   || '';
      if (today < sStart || today > sEnd) return;
      const rateLocal = adults <= 2 ? rp.DBL_Rate : (rp.TRP_Rate || rp.DBL_Rate);
      if (!rateLocal || rateLocal <= 0) return;
      const rateUSD = rateLocal * fxRate;
      if (!hotelRooms2[hotel.Hotel_ID] || rateUSD < hotelRooms2[hotel.Hotel_ID].rateUSD) {
        hotelRooms2[hotel.Hotel_ID] = {
          rateUSD, roomType: room.Room_Type_Name || 'Standard', numRooms: 1,
          hotelName: hotel.Hotel_Name, stars: hotel.Star_Rating || 4, hotelId: hotel.Hotel_ID
        };
      }
    });
    const best = hotelRooms2[hotel.Hotel_ID];
    if (best) {
      const hotelUSD = Math.round(best.rateUSD * nights2 * adults);
      const svcUSD   = Math.round(svcRaw2 * fxRate);
      const totalUSD = Math.round((hotelUSD + svcUSD) * markup);
      opts2.push({ ...best, hotelUSD, svcUSD, totalUSD, nights: nights2 });
    }
  });

  opts2.sort((a,b) => a.totalUSD - b.totalUSD);
  const tiers2 = ['اقتصادية','فضية','ذهبية'];
  opts2.slice(0,3).forEach((opt, idx) => { opt.tier = tiers2[idx] || tiers2[2]; });

  if (opts2.length > 0) {
    pricingText += `\n--- أسعار سانت بطرسبرغ (${nights2} ليالي) ---\n`;
    opts2.slice(0,3).forEach(opt => {
      pricingText += `\nباقة ${opt.tier}: ${opt.hotelName} ${'⭐'.repeat(opt.stars)}\n`;
      pricingText += `${nights2} ليالي | غرفة ${opt.roomType} | إفطار يومي\n`;
      pricingText += `السعر الإجمالي: $${opt.totalUSD} USD\n`;
      pricingText += `يشمل:\n${buildInclusions(destination, nights2)}\n`;
    });
  }
}

return [{ json: { ...prev, pricingData: pricingText } }];

parameters.jsonBody:
={{ JSON.stringify({
  model: "openai/gpt-4o-mini",
  max_tokens: 300,
  temperature: 0,
  messages: [
    {
      role: "system",
      content: "أنت نظام استخراج بيانات رحلات. استخرج من المحادثة:\n\n- destination: (Kazakhstan / Russia / Poland / Uzbekistan / Ukraine) أو فاضي\n- city: المدينة الأولى (Almaty / Moscow / Saint Petersburg) أو فاضي\n- city2: المدينة الثانية لو الزبون يريد مدينتين (Moscow / Saint Petersburg) أو فاضي\n- nights: عدد الليالي الإجمالي\n  * لو قال X أيام/يوم → nights = X - 1\n  * لو قال X ليالي/ليلة → nights = X (لا تطرح 1)\n- adults: عدد البالغين (0 لو مش محدد)\n- children_ages: مصفوفة أعمار الأطفال أو []\n\nركّز على [CURRENT] أولاً ثم أكمل النواقص من السياق السابق.\nرد بـ JSON فقط: {destination, city, city2, nights, adults, children_ages}"
    },
    {
      role: "user",
      content: "المحادثة:\n" + $('Build AI Context').first().json.chatHistory + "\n[CURRENT] العميل: " + $('Build AI Context').first().json.userMessage
    }
  ]
}) }}
